const users = $('Fetch Users').first().json.users || [];
const bullishText = $('Get Bullish CSV').first().json.data || '';

function parseCSV(text) {
  if (!text) return [];
  const lines = text.split('\n').map(line => line.trim()).filter(line => line.length > 0);
  if (lines.length < 2) return [];

  const headers = lines[0].split(',').map(h => h.replace(/"/g, '').trim());
  const results = [];

  for (let i = 1; i < lines.length; i++) {
    const currentLine = lines[i].split(',').map(val => val.replace(/"/g, '').trim());
    if (currentLine.length < headers.length) continue;

    const row = {};
    headers.forEach((header, index) => {
      row[header] = currentLine[index];
    });
    results.push(row);
  }
  return results;
}

const bullishStocks = parseCSV(bullishText).slice(0, 5);

